#include "ScreenCapture.h"
#include <stdexcept>
using Microsoft::WRL::ComPtr;
std::vector<MonitorInfo> DxgiScreenCapture::ListMonitors(){std::vector<MonitorInfo>v;EnumDisplayMonitors(nullptr,nullptr,[](HMONITOR h,HDC,LPRECT,LPARAM p)->BOOL{MONITORINFOEXW m{};m.cbSize=sizeof(m);GetMonitorInfoW(h,&m);reinterpret_cast<std::vector<MonitorInfo>*>(p)->push_back({m.rcMonitor,(m.dwFlags&MONITORINFOF_PRIMARY)!=0,m.szDevice});return TRUE;},(LPARAM)&v);return v;}
DxgiScreenCapture::DxgiScreenCapture(int i):index_(i){if(!Initialize())throw std::runtime_error("DXGI capture initialization failed");}
bool DxgiScreenCapture::Initialize(){duplication_.Reset();staging_.Reset();context_.Reset();device_.Reset();ComPtr<IDXGIFactory1> f;if(FAILED(CreateDXGIFactory1(IID_PPV_ARGS(&f))))return false;ComPtr<IDXGIAdapter1>a;if(FAILED(f->EnumAdapters1(0,&a)))return false;D3D_FEATURE_LEVEL level;if(FAILED(D3D11CreateDevice(a.Get(),D3D_DRIVER_TYPE_UNKNOWN,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&device_,&level,&context_)))return false;ComPtr<IDXGIOutput>o;if(FAILED(a->EnumOutputs((UINT)index_,&o)))return false;DXGI_OUTPUT_DESC od{};o->GetDesc(&od);size_={od.DesktopCoordinates.right-od.DesktopCoordinates.left,od.DesktopCoordinates.bottom-od.DesktopCoordinates.top};ComPtr<IDXGIOutput1>o1;if(FAILED(o.As(&o1))||FAILED(o1->DuplicateOutput(device_.Get(),&duplication_)))return false;D3D11_TEXTURE2D_DESC d{};d.Width=size_.cx;d.Height=size_.cy;d.MipLevels=d.ArraySize=1;d.Format=DXGI_FORMAT_B8G8R8A8_UNORM;d.SampleDesc.Count=1;d.Usage=D3D11_USAGE_STAGING;d.CPUAccessFlags=D3D11_CPU_ACCESS_READ;return SUCCEEDED(device_->CreateTexture2D(&d,nullptr,&staging_));}
bool DxgiScreenCapture::Capture(cv::Mat&out){DXGI_OUTDUPL_FRAME_INFO info{};ComPtr<IDXGIResource>res;auto hr=duplication_->AcquireNextFrame(5,&info,&res);if(hr==DXGI_ERROR_WAIT_TIMEOUT)return false;if(hr==DXGI_ERROR_ACCESS_LOST){Initialize();return false;}if(FAILED(hr))return false;ComPtr<ID3D11Texture2D>tex;res.As(&tex);context_->CopyResource(staging_.Get(),tex.Get());D3D11_MAPPED_SUBRESOURCE map{};bool ok=false;if(SUCCEEDED(context_->Map(staging_.Get(),0,D3D11_MAP_READ,0,&map))){cv::Mat view(size_.cy,size_.cx,CV_8UC4,map.pData,map.RowPitch);view.copyTo(out);context_->Unmap(staging_.Get(),0);ok=true;}duplication_->ReleaseFrame();return ok;}
